% exp_026: arXiv Filtering Strategy Comparison
% Usage: \input{tables/exp_026_arxiv_filtering.tex}
% Requires: booktabs, multirow

% ============================================================
% Table 1: Summary (mean ± std over 5 seeds)
% ============================================================
\begin{table}[t]
\centering
\small
\caption{
  Effect of arXiv filtering strategies on downstream benchmark performance.
  Models are Qwen-1.5B fine-tuned with LoRA (rank=4) on arXiv-sourced
  generational depth chains under three contamination filtering strategies.
  Results report mean $\pm$ std over 5 random seeds (42, 123, 456, 789, 1024).
  Best result per metric is \textbf{bolded}.
  Paired $t$-tests are computed against \textsc{No Filter} as the reference.
  Significance: {$^{*}$}\,$p<0.05$,
  {$^{**}$}\,$p<0.01$,
  {$^{***}$}\,$p<0.001$.
}
\label{tab:exp026-arxiv-filtering}
\begin{tabular}{lcc}
\toprule
\textbf{Strategy} & \textbf{MMLU} & \textbf{HellaSwag} \\
\midrule
\textsc{No Filter}
  & 0.5899\;{\scriptsize$\pm$\,0.0008}
  & 0.6600\;{\scriptsize$\pm$\,0.0002} \\
\textsc{Binary}
  & 0.5876\;{\scriptsize$\pm$\,0.0004}
  & \textbf{0.6642}\;{\scriptsize$\pm$\,0.0004} \\
\textsc{Graduated} ($\alpha\!=\!0.9$)
  & \textbf{0.5900}\;{\scriptsize$\pm$\,0.0011}
  & 0.6599\;{\scriptsize$\pm$\,0.0003} \\
\midrule
\multicolumn{3}{l}{\textit{Paired $t$-test vs.\ \textsc{No Filter}}} \\
\quad \textsc{Binary}
  & $p=0.005^{**}$
  & $p<0.001^{***}$ \\
\quad \textsc{Graduated}
  & $p=0.692$
  & $p=0.245$ \\
\bottomrule
\end{tabular}
\end{table}

